import React from 'react';
import { View } from 'react-native';

import { RegisterMenu } from '../../components/Pop-Ups/RegisterMenu';
import { PaymentMenu } from '../../components/Pop-Ups/PaymentMenu';
import { ShoppingCart } from '../../components/Pop-Ups/ShoppingCart';
import { AnimatedImage } from '../../components/AnimatedImage';
import { CustomHeader } from '../../components/CustomHeader';
import { RenderList } from '../../components/RenderList';
import { SearchBar } from '../../components/SearchBar';
import { Keyboard } from '../../components/Pop-Ups/Keyboard';
import { Alert } from '../../components/Pop-Ups/Alert';

import { styles } from './styles';

export default function Home() {
  const {AlertTSX} = Alert
  function Header() {
    return (
      <View>
        <AnimatedImage />
        <CustomHeader />
        < SearchBar />
      </View>
    );
  };

  function PopUps() {
    return (
      <>
        <Keyboard />
        <PaymentMenu />
        <ShoppingCart />
        <RegisterMenu />
        <AlertTSX />
      </>
    );
  };

  return (
    <View style={styles.container}>
      <Header />
      <RenderList />
      <PopUps />
    </View >
  );
}
